exercise.referenceSolution:
#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        return 0;
    }
    int values[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    int pivot = values[n - 1];
    int store = 0;
    for (int i = 0; i < n - 1; i++) {
        if (values[i] < pivot) {
            int t = values[i];
            values[i] = values[store];
            values[store] = t;
            store++;
        }
    }
    values[n - 1] = values[store];
    values[store] = pivot;
    printf("%d\n", store);
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d\n", values[i]);
    }
    return 0;
}

