#include <stdio.h>

static int values[100000];

static void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

static int partition(int lo, int hi) {
    swap(&values[lo + (hi - lo) / 2], &values[hi]);
    int pivot = values[hi];
    int store = lo;
    for (int i = lo; i < hi; i++) {
        if (values[i] < pivot) {
            swap(&values[i], &values[store++]);
        }
    }
    swap(&values[store], &values[hi]);
    return store;
}

static void quick_sort(int lo, int hi) {
    if (lo >= hi) {
        return;
    }
    int p = partition(lo, hi);
    quick_sort(lo, p - 1);
    quick_sort(p + 1, hi);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100000) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    quick_sort(0, n - 1);
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d\n", values[i]);
    }
    return 0;
}

