#include <stdio.h>

static int values[100000];

static void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

static int partition(int lo, int hi) {
    swap(&values[lo + (hi - lo) / 2], &values[hi]);
    int pivot = values[hi];
    int store = lo;
    for (int i = lo; i < hi; i++) {
        if (values[i] < pivot) {
            swap(&values[i], &values[store++]);
        }
    }
    swap(&values[store], &values[hi]);
    return store;
}

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2 || n < 1 || n > 100000 || k < 1 || k > n) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    int target = k - 1;
    int lo = 0, hi = n - 1;
    while (lo < hi) {
        int p = partition(lo, hi);
        if (p == target) {
            break;
        }
        if (target < p) {
            hi = p - 1;
        } else {
            lo = p + 1;
        }
    }
    printf("%d\n", values[target]);
    return 0;
}
